{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE table snitch_db.maplemonk.Pre_final_RTS_automation as WITH po_base AS ( SELECT CASE WHEN REGEXP_LIKE(UPPER(TRIM(sKU_GROUP)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sKU_GROUP)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sKU_GROUP)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sKU_GROUP)), \'.*-[0-9]$\') THEN REGEXP_REPLACE( UPPER(TRIM(sKU_GROUP)), \'-([0-9])$\', \'-0\\1\' ) ELSE UPPER(TRIM(sKU_GROUP)) END AS SKU_GROUP, REGEXP_REPLACE( CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku_group)) END, \'-[^-]+$\', \'\' ) AS sku_code, REGEXP_SUBSTR( CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku_group)) END, \'[^-]+$\' ) AS colour_code, TRY_TO_DATE(TO_VARCHAR(order_date), \'DD/MM/YYYY\') AS order_date, transfer_branch_code, lot_number, total_qty, CASE WHEN transfer_branch_code = 8 THEN \'SOUTH\' WHEN transfer_branch_code = 94 THEN \'NORTH\' END AS po_side FROM snitch_db.maplemonk.logic_purchase_order WHERE sku_group LIKE \'%-%\' ), po_ranked AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY sku_group, po_side ORDER BY order_date DESC NULLS LAST, lot_number DESC ) AS rn FROM po_base ), po_sku_colours AS ( SELECT sku_code, COUNT(DISTINCT colour_code) AS total_colours FROM po_base GROUP BY 1 ), latest_po_keys AS ( SELECT sku_group, MAX(CASE WHEN po_side = \'SOUTH\' AND rn = 1 THEN lot_number END) AS south_po, MAX(CASE WHEN po_side = \'NORTH\' AND rn = 1 THEN lot_number END) AS north_po FROM po_ranked GROUP BY 1 ), latest_po AS ( SELECT lpk.sku_group, lpk.south_po, lpk.north_po, SUM( CASE WHEN pb.po_side = \'SOUTH\' AND pb.lot_number = lpk.south_po THEN pb.total_qty ELSE 0 END ) AS south_po_qty, SUM( CASE WHEN pb.po_side = \'NORTH\' AND pb.lot_number = lpk.north_po THEN pb.total_qty ELSE 0 END ) AS north_po_qty FROM latest_po_keys lpk LEFT JOIN po_base pb ON lpk.sku_group = pb.sku_group GROUP BY 1,2,3 ), ALLOCATED AS ( SELECT SKU_GROUP, MAX( CASE WHEN WAREHOUSE = \'TAURU\' THEN PLANNED_DATE END ) AS planned_date_north, MAX( CASE WHEN WAREHOUSE = \'YLKWH\' THEN PLANNED_DATE END ) AS planned_date_south FROM ( SELECT SKU_GROUP, PLANNED_DATE, WAREHOUSE, ROW_NUMBER() OVER ( PARTITION BY SKU_GROUP, WAREHOUSE ORDER BY PLANNED_DATE DESC ) AS rn FROM SNITCH_DB.MAPLEMONK.DAILY_INWARD_AND_OPERATION_REPORT WHERE WAREHOUSE IN (\'TAURU\', \'YLKWH\') ) a WHERE rn = 1 GROUP BY SKU_GROUP ), meta_mapping as ( select sku_group, L1_CATEGORY, category, meta1, meta2, meta3 from snitch_db.maplemonk.meta_mapping_cogs_sku ), planned_month as ( SELECT cleaned_sku, CASE WHEN SUM(CASE WHEN remarks_final ILIKE \'April%\' THEN 1 ELSE 0 END) > 0 AND SUM(CASE WHEN remarks_final ILIKE \'May%\' THEN 1 ELSE 0 END) > 0 THEN \'APRIL-MAY\' WHEN SUM(CASE WHEN remarks_final ILIKE \'April%\' THEN 1 ELSE 0 END) > 0 THEN \'APRIL\' WHEN SUM(CASE WHEN remarks_final ILIKE \'May%\' THEN 1 ELSE 0 END) > 0 THEN \'MAY\' ELSE NULL END AS planned_month FROM snitch_db.maplemonk.inwards_list_mom_v2_sku_list_with_month_remarks GROUP BY cleaned_sku ), qc_base AS ( SELECT DISTINCT CASE WHEN REGEXP_LIKE(UPPER(TRIM(p.sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(p.sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(p.sku_group)) END AS sku_group, REGEXP_REPLACE( CASE WHEN REGEXP_LIKE(UPPER(TRIM(p.sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(p.sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(p.sku_group)) END, \'-[^-]+$\', \'\' ) AS sku_code, REGEXP_SUBSTR( CASE WHEN REGEXP_LIKE(UPPER(TRIM(p.sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(p.sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(p.sku_group)) END, \'[^-]+$\' ) AS colour_code, p.vendor_name, p.north_qty, p.south_qty, p.total_qty, p.qc_status, p.created_at, p.inspection_date FROM snitch_db.maplemonk.qc_report_with_vendor p ), sku_class as ( SELECT SKU_GROUP , SKU_CLASS FROM SNITCH_DB.MAPLEMONK.AVAILABILITY_MASTER_V2 ), qc_colour_counts AS ( SELECT sku_code, COUNT(DISTINCT CASE WHEN qc_status ILIKE \'pass\' THEN colour_code END) AS colours FROM qc_base GROUP BY sku_code ), collection_dedup AS ( SELECT sku, ANY_VALUE(collection) AS collection FROM snitch_db.maplemonk.collection_sku_mapped GROUP BY 1 ), collection_count AS ( SELECT collection, count(distinct sku) AS collection_count, FROM snitch_db.maplemonk.collection_sku_mapped GROUP BY 1 ), collection_qc AS ( SELECT c.collection, COUNT(DISTINCT c.sku) AS collection_qc_passed FROM snitch_db.maplemonk.collection_sku_mapped c INNER JOIN qc_base q ON c.sku = q.sku_group WHERE q.qc_status ILIKE \'pass\' GROUP BY c.collection ), photoshoot_dedup AS ( SELECT sku_group, shoot_date, sample_received_date FROM snitch_db.maplemonk.sku_group_sample_to_live QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY CASE WHEN shoot_date IS NOT NULL THEN 0 ELSE 1 END, shoot_date DESC ) = 1 ), final_base AS ( SELECT qcb.sku_group, qcb.sku_code, qcb.colour_code, mm.l1_category, mm.category, mm.meta1, mm.meta2, mm.meta3, sc.sku_class, CASE WHEN sc.sku_class IN (\'2-Belly\',\'1-Head\',\'3-Tail\') THEN \'Repeat\' END AS repeat_remarks, qcb.vendor_name, lp.south_po, lp.north_po, lp.south_po_qty, lp.north_po_qty, qcb.north_qty, qcb.south_qty, qcb.total_qty, qcb.qc_status, qcb.created_at, qcb.inspection_date, qcc.colours, ps.total_colours AS po_colours, ph.sample_received_date, ph.shoot_date, a.planned_date_north, a.planned_date_south, cc.collection_count, COALESCE(cq.collection_qc_passed, 0) AS collection_qc, c.collection, CASE WHEN qcc.colours = ps.total_colours THEN \'COLOURS - READY\' WHEN qcc.colours < ps.total_colours THEN \'COLOURS - PENDING\' ELSE \'PO-ISSUE\' END AS colour_remarks, CASE WHEN ph.shoot_date IS NULL AND ph.sample_received_date IS NOT NULL AND CURRENT_DATE > DATEADD(day, 3, ph.sample_received_date) THEN \'PHOTOSHOOT - PASS\' WHEN ph.shoot_date IS NULL AND ph.sample_received_date IS NOT NULL THEN \'SAMPLE - RECEIVED\' WHEN ph.sample_received_date IS NULL THEN \'SAMPLE - NOT RECEIVED\' WHEN ph.shoot_date IS NOT NULL THEN \'PHOTOSHOOT - DONE\' END AS photoshoot_remarks, CASE WHEN c.collection IS NULL THEN \'Not COLLECTION\' WHEN cc.collection_count = COALESCE(cq.collection_qc_passed, 0) THEN \'COLLECTION - QC Passed\' WHEN cc.collection_count > COALESCE(cq.collection_qc_passed, 0) THEN \'COLLECTION - QC Pending\' ELSE \'Not COLLECTION\' END AS collection_remarks, pm.planned_month, CASE WHEN a.planned_date_north IS NOT NULL AND a.planned_date_south IS NOT NULL THEN \'ALREADY ALLOCATED\' WHEN COALESCE(TRY_TO_NUMBER(qcb.north_qty), 0) = 0 AND a.planned_date_north IS NULL AND COALESCE(TRY_TO_NUMBER(qcb.south_qty), 0) > 0 AND a.planned_date_south IS NOT NULL THEN \'ALREADY ALLOCATED\' WHEN COALESCE(TRY_TO_NUMBER(qcb.south_qty), 0) = 0 AND a.planned_date_south IS NULL AND COALESCE(TRY_TO_NUMBER(qcb.north_qty), 0) > 0 AND a.planned_date_north IS NOT NULL THEN \'ALREADY ALLOCATED\' ELSE \'ALLOCATE\' END AS allocation_remarks FROM qc_base qcb LEFT JOIN qc_colour_counts qcc ON qcb.sku_code = qcc.sku_code LEFT JOIN po_sku_colours ps ON qcb.sku_code = ps.sku_code LEFT JOIN latest_po lp ON qcb.sku_group = lp.sku_group LEFT JOIN collection_dedup c ON c.sku = qcb.sku_group LEFT JOIN collection_count cc ON c.collection = cc.collection LEFT JOIN collection_qc cq ON c.collection = cq.collection LEFT JOIN photoshoot_dedup ph ON qcb.sku_group = ph.sku_group LEFT JOIN planned_month pm ON qcb.sku_group = pm.cleaned_sku LEFT JOIN allocated a ON qcb.sku_group = a.sku_group LEFT JOIN meta_mapping mm ON mm.sku_group = qcb.sku_group LEFT JOIN sku_class sc ON qcb.sku_group = sc.sku_group ) SELECT *, CASE WHEN repeat_remarks IS NOT NULL AND allocation_remarks <> \'ALLOCATE\' THEN \'ALREADY ALLOCATED - REPEAT\' WHEN repeat_remarks IS NOT NULL AND allocation_remarks = \'ALLOCATE\' THEN \'ALLOCATABLE\' WHEN colour_remarks <> \'COLOURS - READY\' THEN \'NON-ALLOCATABLE - COLOURS PENDING\' WHEN colour_remarks = \'COLOURS - READY\' AND photoshoot_remarks NOT IN (\'PHOTOSHOOT - DONE\', \'PHOTOSHOOT - PASS\') THEN \'NON-ALLOCATABLE - SAMPLE PENDING\' WHEN colour_remarks = \'COLOURS - READY\' AND photoshoot_remarks IN (\'PHOTOSHOOT - DONE\', \'PHOTOSHOOT - PASS\') AND collection_remarks <> \'Not COLLECTION\' AND collection_remarks <> \'COLLECTION - QC Passed\' THEN \'NON-ALLOCATABLE - COLLECTION QC PENDING\' WHEN colour_remarks = \'COLOURS - READY\' AND photoshoot_remarks IN (\'PHOTOSHOOT - DONE\', \'PHOTOSHOOT - PASS\') AND ( collection_remarks = \'Not COLLECTION\' OR collection_remarks = \'COLLECTION - QC Passed\' ) AND allocation_remarks <> \'ALLOCATE\' THEN \'ALREADY ALLOCATED\' ELSE \'ALLOCATABLE\' END AS final_remarks FROM final_base;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            